-- =============================================================================
-- 457 — LE CAHIER D'EXERCICES DE 3E (partie retouche)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 457 --niveau 3e --fichiers histoire-geo.k012 --suffixe retouche > supabase/contenu/457_exercices_3e_retouche.sql
--
-- 27 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.k012       27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('2a360b9e-58d4-5d2c-99aa-1ed25cbbb4c8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quelles communes entrent dans la couronne ?","competence":"lire-tableau","situation":"Autour de Valmont, une ville imaginée pour l’exercice, l’INSEE étudie quatre communes voisines. Pour chacune, il a compté les actifs qui partent travailler dans le pôle urbain.","documents":[{"id":"communes","type":"tableau","titre":"Les actifs de quatre communes voisines","source":"Chiffres écrits pour l’exercice.","colonnes":["Commune","Habitants","Actifs","Actifs qui travaillent dans le pôle"],"lignes":[["Champlan","3 400","1 500","62 %"],["Les Hauts-Bois","900","400","38 %"],["Saint-Aubin","2 100","1 000","47 %"],["Marcouville","600","250","12 %"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la part d’actifs des **deux communes** qui font partie de la couronne périurbaine de Valmont.","aide":"Une commune entre dans la couronne si au moins 40 % de ses actifs travaillent dans le pôle.","type":"zone","document":"communes","multiple":true},{"enonce":"Combien d’actifs de **Saint-Aubin** partent travailler dans le pôle de Valmont ?","aide":"Calcule 47 % de 1 000 actifs : 1 000 × 47 ÷ 100.","type":"nombre","unite":"actifs"},{"enonce":"Que peut-on dire des **Hauts-Bois** ?","aide":"Compare 38 % au seuil de 40 %.","type":"choix","options":[{"id":"a","texte":"Ils appartiennent à la couronne, car 38 % est proche de 40 %."},{"id":"b","texte":"Ils sont une ville-centre, car leur part est supérieure à 10 %."},{"id":"c","texte":"Ils n’appartiennent pas à la couronne, car 38 % est inférieur à 40 %."},{"id":"d","texte":"Ils appartiennent au pôle urbain, car ils comptent 400 actifs."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3","r2c3"]},"explication":"Champlan (**62 %**) et Saint-Aubin (**47 %**) dépassent le seuil de 40 %. Les Hauts-Bois (38 %) le frôlent sans l’atteindre, Marcouville (12 %) en est loin."},{"cle":{"type":"nombre","valeur":470,"tolerance":0},"affichage":"470 actifs","explication":"47 % de 1 000 = **470 actifs**. Chaque matin, près d’un actif sur deux quitte la commune pour le pôle : ce sont des mobilités pendulaires."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le seuil est strict : **38 % < 40 %**, donc la commune reste hors de la couronne. Elle n’est pourtant pas indifférente à la ville : plus d’un actif sur trois y travaille."}]$ex$::jsonb),
  ('2a360b9e-58d4-5d2c-99aa-1ed25cbbb4c8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Paris et les autres : un palmarès très inégal","competence":"lire-graphique","situation":"Clara compare les plus grandes aires urbaines de France. Elle place les villes sur une carte et lit les populations sur un graphique.","documents":[{"id":"carte","type":"carte","titre":"Cinq grandes villes françaises","fond":"france","lieux":[{"id":"z1","lieu":"paris","symbole":"point","nom":"Paris"},{"id":"z2","lieu":"lyon","symbole":"point","nom":"Lyon"},{"id":"z3","lieu":"marseille","symbole":"point","nom":"Marseille"},{"id":"z4","lieu":"lille","symbole":"point","nom":"Lille"},{"id":"z5","lieu":"toulouse","symbole":"point","nom":"Toulouse"}]},{"id":"pop","type":"graphique","forme":"barres-h","titre":"Population des aires urbaines","source":"Chiffres arrondis, ordre de grandeur, d’après l’INSEE.","categories":["Paris","Lyon","Marseille","Lille","Toulouse"],"series":[{"nom":"Population","valeurs":[13,2.3,1.9,1.5,1.4],"teinte":"violet"}],"axeY":{"titre":"Habitants","unite":"en millions","min":0,"max":14,"pas":2},"valeurs":false}],"questions":[{"enonce":"Sur la carte, touche la ville dont l’aire urbaine est la **plus peuplée** du pays (regarde le graphique).","aide":"Cherche la barre la plus longue du graphique, puis retrouve cette ville sur la carte.","type":"zone","document":"carte","multiple":false},{"enonce":"Paris compte environ combien de fois plus d’habitants que Lyon, la deuxième ? Arrondis à l’unité.","aide":"Divise la population de Paris par celle de Lyon : 13 ÷ 2,3.","type":"nombre","unite":"fois"},{"enonce":"Associe chaque ville à sa région.","aide":"Lille est dans le nord du pays, Marseille au bord de la Méditerranée.","type":"association","gauche":[{"id":"g0","texte":"Lyon"},{"id":"g1","texte":"Lille"},{"id":"g2","texte":"Toulouse"},{"id":"g3","texte":"Marseille"}],"droite":[{"id":"d0","texte":"Hauts-de-France"},{"id":"d1","texte":"Auvergne-Rhône-Alpes"},{"id":"d2","texte":"Provence-Alpes-Côte d’Azur"},{"id":"d3","texte":"Occitanie"}]},{"enonce":"Que montre ce graphique sur la hiérarchie urbaine française ?","aide":"Compare la barre de Paris à toutes les autres.","type":"choix","options":[{"id":"a","texte":"Toulouse est plus peuplée que Lyon."},{"id":"b","texte":"Les cinq villes ont des populations voisines."},{"id":"c","texte":"Une seule ville domine très largement les autres."},{"id":"d","texte":"Les métropoles régionales dépassent Paris."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est **Paris**, avec environ 13 millions d’habitants : environ un Français sur cinq vit dans son aire urbaine."},{"cle":{"type":"nombre","valeur":6,"tolerance":0.5},"affichage":"6 fois","explication":"13 ÷ 2,3 ≈ 5,7, soit **6 fois** plus environ. La hiérarchie urbaine française est très inégale : Paris écrase les métropoles régionales."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"Lyon est dans **Auvergne-Rhône-Alpes**, Lille dans les **Hauts-de-France**, Toulouse en **Occitanie**, Marseille en **Provence-Alpes-Côte d’Azur**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Paris (13 millions) est loin devant : **une seule ville domine**, les métropoles régionales sont « loin derrière », comme le dit le cours."}]$ex$::jsonb),
  ('2a360b9e-58d4-5d2c-99aa-1ed25cbbb4c8'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Camille et les 35 kilomètres","competence":"analyser-texte","situation":"Camille a quitté la ville pour un village en couronne périurbaine. Son récit, écrit pour l’exercice, raconte ce que ce choix change pour elle… et pour le territoire.","documents":[{"id":"recit","type":"texte","genre":"article","titre":"Le récit de Camille","auteur":"Texte écrit pour l’exercice.","blocs":["Depuis trois ans, Camille habite à Saint-Aubin, un village de 2 100 habitants. Elle y a acheté une maison avec jardin : en ville, le même budget ne lui offrait qu’un petit appartement.","Mais Camille travaille dans le pôle urbain, à 35 km de chez elle. Chaque matin, elle prend sa voiture ; chaque soir, elle rentre après une heure de bouchons.","Le lotissement de Camille a été construit sur d’anciens champs de blé, et deux autres sont en projet. Le maire se demande comment accueillir de nouveaux habitants sans grignoter les terres agricoles."]}],"questions":[{"enonce":"Touche le mot qui désigne la ville où Camille travaille, celle dont dépend son village.","aide":"Dans une aire urbaine, la ville-centre et sa banlieue forment… un quoi ?","type":"zone","document":"recit","multiple":false},{"enonce":"Touche le mot qui montre que le lotissement a pris la place de terres agricoles.","aide":"Que cultivait-on avant les maisons ?","type":"zone","document":"recit","multiple":false},{"enonce":"Camille fait 35 km pour aller travailler et 35 km pour rentrer, cinq jours par semaine. Combien de kilomètres parcourt-elle en une semaine ?","aide":"Un aller-retour, puis cinq jours : 35 × 2 × 5.","type":"nombre","unite":"km"},{"enonce":"Range ces quatre étapes dans l’ordre où elles s’enchaînent pour Camille.","aide":"Commence par la raison du départ, finis par la conséquence sur le territoire.","type":"ordre","items":[{"id":"a","texte":"Les terres agricoles reculent sous les lotissements"},{"id":"b","texte":"Le logement en ville est trop cher"},{"id":"c","texte":"Camille s’installe en couronne périurbaine"},{"id":"d","texte":"Elle fait de longues navettes en voiture"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m38"]},"explication":"Le **pôle** urbain est le cœur de l’aire urbaine ; Saint-Aubin, d’où l’on part travailler vers lui, appartient à sa couronne périurbaine."},{"cle":{"type":"zone","ids":["m71"]},"explication":"Le lotissement est sur d’anciens **champs** : c’est l’**artificialisation** des sols. Deux lotissements de plus, et les terres agricoles reculent : c’est le mitage des campagnes."},{"cle":{"type":"nombre","valeur":350,"tolerance":0},"affichage":"350 km","explication":"35 × 2 = 70 km par jour, et 70 × 5 = **350 km par semaine** : ce sont des mobilités pendulaires longues, typiques de la périurbanisation."},{"cle":{"type":"ordre","ids":["b","c","d","a"]},"explication":"Prix du logement → installation en couronne → navettes plus longues → terres artificialisées : c’est la chaîne de l’**étalement urbain**."}]$ex$::jsonb),
  ('174488ca-afc4-5157-984c-e59610dde149'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Cinquante ans d’usines en moins","competence":"lire-graphique","situation":"Dans un dossier sur l’industrie française, Hugo trouve un graphique sur les emplois de l’industrie manufacturière depuis 1974.","documents":[{"id":"emplois","type":"graphique","forme":"barres","titre":"Emplois de l’industrie manufacturière en France","source":"Chiffres arrondis, ordre de grandeur, d’après l’INSEE.","categories":["1974","1990","2000","2010","2019"],"series":[{"nom":"Emplois","valeurs":[5.2,4.4,3.9,3.1,2.7],"teinte":"bleu"}],"axeY":{"titre":"Emplois","unite":"en millions","min":0,"max":6,"pas":1},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Touche l’année où l’industrie employait le **plus** de monde.","aide":"Cherche la barre la plus haute.","type":"zone","document":"emplois","multiple":false},{"enonce":"Combien d’emplois industriels ont disparu entre 1974 et 2019 ? Réponds en millions.","aide":"Soustrais la dernière valeur à la première : 5,2 − 2,7.","type":"nombre","unite":"millions"},{"enonce":"Quel mot désigne cette perte massive d’emplois industriels depuis les années 1970 ?","aide":"Le préfixe « dés- » exprime un mouvement de recul.","type":"choix","options":[{"id":"a","texte":"La métropolisation du territoire"},{"id":"b","texte":"La désindustrialisation du pays"},{"id":"c","texte":"La littoralisation des activités"},{"id":"d","texte":"La tertiarisation de l’économie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"C’est **1974** : environ 5,2 millions d’emplois industriels. Ensuite, chaque barre est plus basse que la précédente."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0.1},"affichage":"2,5 millions","explication":"5,2 − 2,7 = **2,5 millions** d’emplois en moins, soit près de la moitié : c’est la **désindustrialisation**."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est la **désindustrialisation** : l’industrie a perdu environ la moitié de ses emplois depuis les années 1970."}]$ex$::jsonb),
  ('174488ca-afc4-5157-984c-e59610dde149'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"La carte de l’industrie qui a changé de lieu","competence":"lire-carte","situation":"Léa prépare une carte de l’industrie française : d’un côté des zones industrialo-portuaires, de l’autre des espaces en difficulté ou en réussite.","documents":[{"id":"carte","type":"carte","titre":"Quelques lieux de l’industrie","fond":"france","lieux":[{"id":"z1","lieu":"dunkerque","symbole":"point","nom":"Dunkerque"},{"id":"z2","lieu":"le-havre","symbole":"point","nom":"Le Havre"},{"id":"z3","lon":4.94,"lat":43.44,"symbole":"point","nom":"Marseille-Fos"},{"id":"z4","lieu":"toulouse","symbole":"point","nom":"Toulouse"},{"id":"z5","lon":7.05,"lat":43.62,"symbole":"point","nom":"Sophia Antipolis"},{"id":"z6","lieu":"metz","symbole":"point","nom":"Lorraine (Metz)"}]}],"questions":[{"enonce":"Touche **les trois** grandes zones industrialo-portuaires de la carte.","aide":"Ces zones sont au contact de la mer : Mer du Nord, Manche, Méditerranée.","type":"zone","document":"carte","multiple":true},{"enonce":"Associe chaque zone industrialo-portuaire à son littoral.","aide":"Dunkerque est tout au nord, près de la Belgique.","type":"association","gauche":[{"id":"g0","texte":"Dunkerque"},{"id":"g1","texte":"Le Havre"},{"id":"g2","texte":"Marseille-Fos"}],"droite":[{"id":"d0","texte":"Mer du Nord"},{"id":"d1","texte":"Méditerranée"},{"id":"d2","texte":"Manche"}]},{"enonce":"Range chaque lieu : l’industrie y recule ou y progresse ?","aide":"Pense aux friches d’un côté, aux technopôles et aux ports de l’autre.","type":"categories","categories":[{"id":"c0","texte":"Espace qui perd des emplois industriels"},{"id":"c1","texte":"Espace industriel qui gagne"}],"items":[{"id":"i0","texte":"La zone industrialo-portuaire du Havre"},{"id":"i1","texte":"L’Aerospace Valley autour de Toulouse"},{"id":"i2","texte":"Sophia Antipolis, technopôle"},{"id":"i3","texte":"Les anciennes mines et sidérurgies de Lorraine"},{"id":"i4","texte":"Les friches industrielles du Nord"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2","z3"]},"explication":"Les trois ZIP sont **Dunkerque**, **Le Havre** et **Marseille-Fos** : les industries lourdes s’installent près des ports qui reçoivent les matières premières importées."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Dunkerque** borde la mer du Nord, **Le Havre** la Manche, **Marseille-Fos** la Méditerranée. Le littoral est une interface avec le monde."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Le Nord et la Lorraine gardent des **friches industrielles**. Les technopôles, l’Aerospace Valley et les ZIP gagnent : l’industrie ne disparaît pas, ses lieux se déplacent."}]$ex$::jsonb),
  ('174488ca-afc4-5157-984c-e59610dde149'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La fermeture de l’usine Valmy","competence":"analyser-document","situation":"Le journal de la ville imaginée de Valmy raconte la fermeture de l’usine de moteurs. Le texte et le tableau ont été écrits pour l’exercice.","documents":[{"id":"note","type":"texte","genre":"article","titre":"Note du comité d’entreprise","auteur":"Texte écrit pour l’exercice.","blocs":["En 1990, l’usine de Valmy fabrique des moteurs avec 800 ouvriers. Dans les années 2000, la direction installe des robots : on produit autant avec moins de monde.","En 2012, une partie de la production est déplacée dans un pays où les salaires sont plus bas : c’est une délocalisation. Il ne reste que 320 salariés. L’usine aujourd’hui ne fabrique plus que des pièces de haute technologie."]},{"id":"emplois","type":"tableau","titre":"Les emplois de l’usine","source":"Chiffres écrits pour l’exercice.","colonnes":["Année","1990","2005","2012","2020"],"lignes":[["Salariés","800","600","320","320"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne le transfert d’une production vers un pays où les salaires sont plus bas.","aide":"Ce mot commence par « dé- » et contient « lieu ».","type":"zone","document":"note","multiple":false},{"enonce":"Touche le mot qui explique qu’on produise autant avec moins d’ouvriers.","aide":"Quelles machines remplacent des gestes humains ?","type":"zone","document":"note","multiple":false},{"enonce":"Entre 1990 et 2020, de combien de pour cent les emplois de l’usine ont-ils baissé ?","aide":"Calcule la perte : 800 − 320 = 480, puis 480 ÷ 800.","type":"nombre","unite":"%"},{"enonce":"Que dit cet exemple sur l’industrie française ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Elle a recruté beaucoup plus d’ouvriers qu’en 1990 dans cette usine."},{"id":"b","texte":"Elle ne fabrique plus rien en France depuis la fermeture de 2012."},{"id":"c","texte":"Elle a entièrement disparu de la ville depuis les années 1990."},{"id":"d","texte":"Elle perd des emplois, mais l’usine se spécialise dans la haute technologie."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m49"]},"explication":"C’est la **délocalisation** : produire ailleurs, là où la main-d’œuvre coûte moins cher."},{"cle":{"type":"zone","ids":["m20"]},"explication":"Ce sont les **robots** : l’automatisation permet de produire autant avec moins d’ouvriers, une autre cause de la désindustrialisation."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 %","explication":"800 − 320 = 480 emplois perdus ; 480 ÷ 800 = 0,6, soit une baisse de **60 %**."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’usine garde **320 salariés** et fabrique des pièces de haute technologie : l’industrie ne disparaît pas, elle se transforme et ses lieux se déplacent."}]$ex$::jsonb),
  ('d0b9a0a7-1354-5e70-b8a7-ca9d337f0a05'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La carte des grandes productions","competence":"lire-carte","situation":"Nina colorie une carte des spécialisations agricoles de la France : chaque symbole marque un paysage et une production.","documents":[{"id":"carte","type":"carte","titre":"Quelques grandes productions agricoles","fond":"france","lieux":[{"id":"z1","lon":1.6,"lat":48.2,"symbole":"carre","teinte":"ambre","nom":"Beauce"},{"id":"z2","lon":-3,"lat":48.2,"symbole":"triangle","teinte":"vert","nom":"Bretagne"},{"id":"z3","lieu":"bordeaux","symbole":"etoile","teinte":"rose","nom":"Bordeaux"},{"id":"z4","lieu":"reims","symbole":"etoile","teinte":"rose","nom":"Champagne"}],"legende":[{"teinte":"ambre","texte":"Grandes cultures céréalières"},{"teinte":"vert","texte":"Élevage, dont hors-sol"},{"teinte":"rose","texte":"Vignobles"}]}],"questions":[{"enonce":"Touche **les deux** repères qui marquent des régions de vignobles.","aide":"Regarde la légende : quel symbole marque les vignobles ?","type":"zone","document":"carte","multiple":true},{"enonce":"Quel paysage domine en Beauce, région de grandes cultures céréalières ?","aide":"Pense à de très grandes parcelles sans clôture ni haies.","type":"choix","options":[{"id":"a","texte":"La forêt de conifères, épaisse et continue"},{"id":"b","texte":"Le bocage, avec des haies et de petits champs"},{"id":"c","texte":"L’openfield, de vastes champs ouverts sans haies"},{"id":"d","texte":"La vigne, plantée en terrasses sur des coteaux"}],"multiple":false},{"enonce":"Associe chaque région à sa spécialisation.","aide":"Le hors-sol, c’est l’élevage en bâtiment : pense aux porcs.","type":"association","gauche":[{"id":"g0","texte":"Beauce"},{"id":"g1","texte":"Bretagne"},{"id":"g2","texte":"Bordeaux"},{"id":"g3","texte":"Midi méditerranéen"}],"droite":[{"id":"d0","texte":"Élevage hors-sol de porcs et de volailles"},{"id":"d1","texte":"Viticulture"},{"id":"d2","texte":"Fruits et légumes irrigués"},{"id":"d3","texte":"Grandes cultures céréalières"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3","z4"]},"explication":"**Bordeaux** et la **Champagne** sont des régions de vignobles. La viticulture est l’une des grandes spécialisations régionales de la France."},{"cle":{"type":"choix","ids":["c"]},"explication":"En Beauce, on trouve l’**openfield** : de vastes champs ouverts, adaptés à la mécanisation des céréales. Le bocage appartient plutôt à l’Ouest."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Chaque région se **spécialise** : céréales en Beauce, élevage hors-sol en Bretagne, vignes à Bordeaux, fruits et légumes irrigués dans le Midi."}]$ex$::jsonb),
  ('d0b9a0a7-1354-5e70-b8a7-ca9d337f0a05'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Moins de fermes, mais plus grandes","competence":"lire-graphique","situation":"Dans un dossier sur les campagnes, Samy compare le nombre d’exploitations agricoles françaises et leur taille moyenne depuis 1970.","documents":[{"id":"nombre","type":"graphique","forme":"barres","titre":"Nombre d’exploitations agricoles","source":"Chiffres arrondis, d’après les recensements agricoles.","categories":["1970","1988","2000","2010","2020"],"series":[{"nom":"Exploitations","valeurs":[1588,1017,664,490,390],"teinte":"vert"}],"axeY":{"titre":"Exploitations","unite":"en milliers","min":0,"max":1800,"pas":200},"valeurs":false},{"id":"taille","type":"graphique","forme":"courbe","titre":"Taille moyenne d’une exploitation","source":"Chiffres arrondis, d’après les recensements agricoles.","categories":["1970","1988","2000","2010","2020"],"series":[{"nom":"Surface moyenne","valeurs":[19,28,42,55,69],"teinte":"ambre"}],"axeY":{"titre":"Surface","unite":"en hectares","min":0,"max":80,"pas":10},"valeurs":false}],"questions":[{"enonce":"Touche l’année où la France comptait le **moins** d’exploitations.","aide":"Cherche la barre la plus basse du premier graphique.","type":"zone","document":"nombre","multiple":false},{"enonce":"Combien d’exploitations ont disparu entre 1970 et 2020 ? Réponds en milliers.","aide":"Soustrais 390 à 1 588.","type":"nombre","unite":"milliers"},{"enonce":"Complète la conclusion.","aide":"Compare les deux graphiques : l’un baisse, l’autre monte.","type":"trous","segments":["Il y a de ",0," d’exploitations, mais elles sont de plus en plus ",1,"."],"banque":["plus en plus","petites","moins en moins","grandes"]},{"enonce":"Quelle agriculture explique cette évolution ?","aide":"Pense aux tracteurs, aux intrants et à la recherche du rendement.","type":"choix","options":[{"id":"a","texte":"Une agriculture qui n’utilise plus aucune machine"},{"id":"b","texte":"Une agriculture productiviste, mécanisée et spécialisée"},{"id":"c","texte":"Une agriculture uniquement tournée vers le bio"},{"id":"d","texte":"Une agriculture réservée à la consommation familiale"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"C’est **2020** : environ 390 000 exploitations, contre près de 1,6 million en 1970."},{"cle":{"type":"nombre","valeur":1198,"tolerance":10},"affichage":"1198 milliers","explication":"1 588 − 390 = **1 198 milliers**, soit près de 1,2 million d’exploitations en moins en cinquante ans."},{"cle":{"type":"trous","trous":[["moins en moins","moins"],["grandes"]]},"affichage":"moins en moins · grandes","explication":"Le nombre d’exploitations baisse (**de moins en moins**), la surface moyenne passe de 19 à 69 hectares (**grandes**) : la mécanisation agrandit les exploitations."},{"cle":{"type":"choix","ids":["b"]},"explication":"Mécanisation, intrants et spécialisation sont les leviers de l’agriculture **productiviste** : elle demande de plus grandes surfaces pour des exploitations moins nombreuses."}]$ex$::jsonb),
  ('d0b9a0a7-1354-5e70-b8a7-ca9d337f0a05'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Produire plus ou produire mieux ?","competence":"argumenter","situation":"Lors d’une sortie sur une ferme bretonne, Lisa (une élève) discute avec Erwan, éleveur de porcs. Leur échange a été écrit pour l’exercice.","documents":[{"id":"dialogue","type":"dialogue","modele":"bulles","titre":"Conversation à la ferme","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Lisa","emoji":"👧","cote":"gauche"},{"nom":"Erwan","emoji":"👨‍🌾","cote":"droite"}],"repliques":[{"qui":"Lisa","texte":"J’ai lu que les nitrates de l’élevage favorisent les algues vertes sur le littoral breton."},{"qui":"Erwan","texte":"C’est vrai. Mais la grande distribution nous impose des prix très bas : je dois produire beaucoup pour vivre."},{"qui":"Lisa","texte":"Certains vendent en circuits courts, ou passent en bio. Et il y a les labels comme l’AOP."},{"qui":"Erwan","texte":"Oui, mais il faut des clients prêts à payer plus cher. Je n’ai pas encore choisi."}]}],"questions":[{"enonce":"Touche le mot qui désigne la pollution des eaux liée à l’élevage intensif.","aide":"Ce mot est lié aux algues vertes, dès la première réplique.","type":"zone","document":"dialogue","multiple":false},{"enonce":"Touche **les deux** mots qui désignent des alternatives à l’élevage intensif.","aide":"Lisa propose des solutions dans sa deuxième réplique.","type":"zone","document":"dialogue","multiple":true},{"enonce":"Pourquoi Erwan dit-il devoir produire beaucoup ?","aide":"Relis la réponse d’Erwan : qui impose quoi ?","type":"choix","options":[{"id":"a","texte":"Parce que les clients refusent tout label."},{"id":"b","texte":"Parce que l’élevage hors-sol n’existe plus."},{"id":"c","texte":"Parce que la PAC interdit les petits élevages."},{"id":"d","texte":"Parce que la grande distribution impose des prix bas."}],"multiple":false},{"enonce":"Range chaque pratique : produire plus ou produire mieux ?","aide":"Le bio, les labels et les circuits courts cherchent la qualité et l’origine.","type":"categories","categories":[{"id":"c0","texte":"Produire plus"},{"id":"c1","texte":"Produire mieux"}],"items":[{"id":"i0","texte":"Élever des porcs en bâtiment, sans pâturage"},{"id":"i1","texte":"Agrandir l’exploitation et acheter un tracteur plus puissant"},{"id":"i2","texte":"Utiliser beaucoup d’engrais pour augmenter le rendement"},{"id":"i3","texte":"Passer en agriculture biologique"},{"id":"i4","texte":"Vendre sa production directement aux habitants"},{"id":"i5","texte":"Obtenir un label AOP"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"Ce sont les **nitrates**, issus des déjections animales et des engrais : ils nourrissent les algues vertes sur les plages bretonnes."},{"cle":{"type":"zone","ids":["m39","m44"]},"explication":"Les **circuits courts** et le **bio** sont deux alternatives en progression. Les labels (AOP, AOC, Label rouge) en sont une troisième."},{"cle":{"type":"choix","ids":["d"]},"explication":"Erwan le dit lui-même : les **prix** imposés par la grande distribution étranglent les revenus, donc il faut produire beaucoup. C’est l’une des tensions du monde agricole."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1","i4":"c1","i5":"c1"}},"explication":"Mécanisation, intrants et hors-sol cherchent le **rendement**. Bio, labels et circuits courts cherchent la **qualité**, l’origine et un lien avec les consommateurs."}]$ex$::jsonb),
